/** Rough category guess from the ingredient word, purely for chip color —
 *  never sent to the model, just a friendly visual cue. */
function guessCategory(word) {
  const w = word.toLowerCase();
  const veg = ["onion", "tomato", "pepper", "garlic", "potato", "carrot", "greens", "spinach", "chili", "cabbage", "cucumber", "eggplant", "bean", "pea", "corn", "broccoli"];
  const grain = ["rice", "pasta", "flour", "bread", "oat", "wheat", "noodle", "quinoa", "peanut", "lentil", "spice", "cumin", "turmeric", "salt", "pepper"];
  const dairyFruit = ["cheese", "milk", "yogurt", "cream", "butter", "lemon", "lime", "mango", "apple", "berry", "berries", "banana", "fig", "grape"];
  if (veg.some((k) => w.includes(k))) return "sage";
  if (grain.some((k) => w.includes(k))) return "saffron";
  if (dairyFruit.some((k) => w.includes(k))) return "plum";
  return "terracotta"; // default: proteins / everything else
}

function scallopPath(w, h, r) {
  let d = `M ${r} 0 `;
  for (let x = r; x + 2 * r <= w; x += 2 * r) d += `a ${r} ${r} 0 0 1 ${2 * r} 0 `;
  for (let y = 0; y + 2 * r <= h; y += 2 * r) d += `a ${r} ${r} 0 0 1 0 ${2 * r} `;
  for (let x = r; x + 2 * r <= w; x += 2 * r) d += `a ${r} ${r} 0 0 1 ${-2 * r} 0 `;
  for (let y = 0; y + 2 * r <= h; y += 2 * r) d += `a ${r} ${r} 0 0 1 0 ${-2 * r} `;
  return d + "Z";
}
const BADGE_PATH = scallopPath(360, 264, 12);

